请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-018

=== 用户原始指令 (query.txt) ===
物流卡要能勾选多个待取包裹,显示'件数:3'这种拼接。读天气,下雨就标'待处理:带伞取件'的注意。点天气区域跳到天气应用看啥时候雨停,素净表面分几块,文字图标,能滚动。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "物流卡要能勾选多个待取包裹,显示'件数:3'这种拼接。读天气,下雨就标'待处理:带伞取件'的注意。点天气区域跳到天气应用看啥时候雨停,素净表面分几块,文字图标,能滚动。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "express": {
        "title": {
          "type": "string",
          "description": "物流卡主对象短标题。",
          "sampleValue": "待取"
        },
        "countLabel": {
          "type": "string",
          "description": "待取包裹件数字符串，按件数与数字拼接展示。",
          "sampleValue": "件数:3"
        },
        "package1": {
          "label": {
            "type": "string",
            "description": "第一件待取包裹的短标签。",
            "sampleValue": "顺丰柜"
          },
          "value": {
            "type": "string",
            "description": "第一件待取包裹的选择值。",
            "sampleValue": "sf_001"
          },
          "selected": {
            "type": "boolean",
            "description": "第一件待取包裹是否已勾选。",
            "sampleValue": true
          }
        },
        "package2": {
          "label": {
            "type": "string",
            "description": "第二件待取包裹的短标签。",
            "sampleValue": "邮政点"
          },
          "value": {
            "type": "string",
            "description": "第二件待取包裹的选择值。",
            "sampleValue": "post_002"
          },
          "selected": {
            "type": "boolean",
            "description": "第二件待取包裹是否已勾选。",
            "sampleValue": false
          }
        },
        "package3": {
          "label": {
            "type": "string",
            "description": "第三件待取包裹的短标签。",
            "sampleValue": "京东站"
          },
          "value": {
            "type": "string",
            "description": "第三件待取包裹的选择值。",
            "sampleValue": "jd_003"
          },
          "selected": {
            "type": "boolean",
            "description": "第三件待取包裹是否已勾选。",
            "sampleValue": false
          }
        },
        "weatherNotice": {
          "type": "string",
          "description": "根据当前天气是否下雨生成的取件注意文案，下雨时提示带伞取件。",
          "sampleValue": "待处理:带伞取件"
        }
      },
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "小雨"
          }
        },
        "daily": {
          "type": "array",
          "description": "天气预报摘要列表。",
          "sampleValue": [
            {
              "rainProbabilityPercent": "73%"
            }
          ],
          "items": {
            "type": "object",
            "properties": {
              "rainProbabilityPercent": {
                "type": "string",
                "description": "当天降雨概率百分比。",
                "sampleValue": "73%"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "快递箱子彩色图标，适合表达物流信息和待取包裹提醒。"
    },
    {
      "src": "resources/base/media/rain.png",
      "description": "云朵和雨滴组合彩色图标，适合表达下雨天气和取件带伞提示。"
    }
  ]
}

